    struct Inventory inv = {{{"bolt", 0}, {"nut", 12}, {"washer", 0}}, {0}, 0};
    check(&inv);
    printf("log: [");
    for (int i = 0; i < inv.log_len; i++) {
        printf("%s\"out of stock: %s\"", i ? ", " : "", inv.log[i]);
    }
    printf("]\n");
}

