// Backs the Go and Python/TypeScript rows of the habit tables.
struct Item {
    name: String,
    count: u32,
}

fn main() {
    // Go: `for _, it := range items { ptrs = append(ptrs, &it) }` becomes a loop over `&items`:
    // each reference points at the element itself, not at a copy.
    let items = vec![
        Item {
            name: "a".into(),
            count: 1,
        },
        Item {
            name: "b".into(),
            count: 2,
        },
    ];
    let mut refs: Vec<&Item> = Vec::new();
    for it in &items {
        refs.push(it);
    }
    assert!(std::ptr::eq(refs[0], &items[0]));
    assert!(std::ptr::eq(refs[1], &items[1]));
    assert_eq!(refs[1].name, "b");
    assert_eq!(refs[1].count, 2);

    // Go: `a[:2]` shares memory. In Rust `to_vec()` is the independent copy,
    // and `split_at_mut` gives two writable halves that cannot overlap.
    let mut a = vec![1, 2, 3, 4];
    let copy = a[..2].to_vec();
    a[2] = 99;
    assert_eq!(copy, [1, 2]);
    let (left, right) = a.split_at_mut(2);
    left[0] = right[0];
    assert_eq!(a, [99, 2, 99, 4]);
}

check-move-out.rs.code:
use std::mem;

// Backs the "what you want" table in "Moving out of a borrow".
fn main() {
    // look at the text inside an Option<String>, keep the Option as it was
    let opt = Some(String::from("abc"));
    assert_eq!(opt.as_deref(), Some("abc"));
    assert_eq!(opt.as_ref().map(|s| s.len()), Some(3));
    assert_eq!(opt, Some(String::from("abc")));

    // take the value, leave None
    let mut opt = Some(String::from("abc"));
    let taken = opt.take();
    assert_eq!(taken, Some(String::from("abc")));
    assert_eq!(opt, None);

    // take a whole String or Vec, leave an empty one
    let mut text = String::from("abc");
    let old = mem::take(&mut text);
    assert_eq!((old.as_str(), text.as_str()), ("abc", ""));
    let mut list = vec![1, 2];
    let old = mem::take(&mut list);
    assert_eq!((old, list), (vec![1, 2], vec![]));

    // take the old value, put a chosen one in
    let mut text = String::from("abc");
    let old = mem::replace(&mut text, String::from("xyz"));
    assert_eq!((old.as_str(), text.as_str()), ("abc", "xyz"));

    // a clone is a second value; the original is still there
    let text = String::from("abc");
    let copy = text.clone();
    assert_eq!(text, copy);
    assert_ne!(text.as_ptr(), copy.as_ptr());
}

